(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--w-sj-prepa-med-j2-ide3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"w-sj-prepa-med-j2-ide3\",\n \"titre\": \"Préparation D.E (J) · J2 Médecine IDE3\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 55,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n   \"sha256\": \"68b60e793e4abc25f93775e01d5e5f49c7e6a0a7361de8eb9b09143d2acbccc2\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Médecine · Prépa D.E J2 (IDE3)\",\n     \"slug\": \"prepa-med-j2-ide3\",\n     \"pages\": \"\",\n     \"count\": 55,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Médecine\",\n     \"source\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__0\",\n       \"num\": \"1\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Quelle affection retenez-vous après la collecte des données de FFF ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hépatite\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Méningite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fièvre typhoïde\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Choléra\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Fièvre typhoïde\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le tableau de FFF réunit les signes du cours : début par céphalées, insomnie, vertiges, épistaxis (moyen mnémotechnique C-I-V-E-T), fièvre en plateau, langue saburrale, tuphos (hébétude, délire) et diarrhée fétide « jus de papaye ». C'est la fièvre typhoïde. Le choléra donne une diarrhée « eau de riz » sans fièvre ; la méningite et l'hépatite n'ont pas ce tableau digestif.\\n\\nSource : Cours de maladies infectieuses et parasitaires, chapitre Fièvre typhoïde (phase d'invasion et phase d'état) ; Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Fièvre typhoïde\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__1\",\n       \"num\": \"2\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Quelle description principale justifie l'affection que vous avez retenue ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Céphalées, vertige, insomnie, saignement endo-nasal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Température de 40°C depuis 3 jours et 86 pulsations par minute\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Diarrhée de selles fétides d'aspect jus de papaye\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Diarrhée de selles fétides, céphalées, insomnie, température de 40°C\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Température de 40°C depuis 3 jours et 86 pulsations par minute\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le signe le plus caractéristique est la dissociation pouls-température : 40 °C avec un pouls à seulement 86/min. Le cours précise qu'à la phase d'état, l'élévation de la température n'est pas suivie d'une élévation du pouls. Les autres propositions sont des signes présents mais moins spécifiques.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, 2.3 Phase d'état (fièvre en plateau avec dissociation du pouls et de la température)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__2\",\n       \"num\": \"3\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Comment nommez-vous ce saignement ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Épistaxis\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hémosialorrhée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hématémèse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hémoptysie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Épistaxis\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un saignement par le nez (endo-nasal) s'appelle une épistaxis ; c'est le « E » de C-I-V-E-T dans la phase d'invasion de la typhoïde. L'hématémèse vient du tube digestif (bouche lors d'un vomissement), l'hémoptysie des voies respiratoires après un effort de toux.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, 2.2 Phase d'invasion\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__3\",\n       \"num\": \"4\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Rappelez la propriété de la vessie de glace chez FFF.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Anti-œdémateux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Antipyrétique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Antalgique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hémostatique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Antipyrétique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La vessie (sac) de glace est un moyen physique de refroidissement : elle sert à faire baisser la température, d'où sa propriété antipyrétique. Le cours la cite parmi les soins devant une fièvre (« mettre un sac de glace sur la tête selon la prescription »).\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, plan de soins de la cirrhose, problème « Fièvre »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__4\",\n       \"num\": \"5\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Identifiez l'agent pathogène de la maladie de FFF parmi les suivants :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Haemophilus influenzae\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bacille de Klebs-Loeffler\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Bacille d'Eberth\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Salmonella typhi\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Salmonella typhi\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'agent de la fièvre typhoïde est Salmonella typhi (et S. paratyphi A, B, C pour les fièvres paratyphoïdes). Haemophilus influenzae et le bacille de Klebs-Loeffler (diphtérie) causent d'autres maladies.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, 2a. Agent pathogène\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__5\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Indiquez les deux principales composantes de votre diagnostic infirmier selon le modèle conceptuel de Virginia Henderson (choisissez une seule réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Problème d'indépendance et mots ou groupe de mots de liaison\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Source de difficultés et Problème d'indépendance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Problème de dépendance et Source de difficultés\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Objectif de soins et intervention infirmière\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Problème de dépendance et Source de difficultés\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Selon le modèle de Virginia Henderson, le diagnostic infirmier relie un problème de dépendance (le besoin perturbé, ex. hyperthermie) à sa source de difficulté (la cause : manque de force, de volonté ou de connaissances…), unis par « relié à ». Les « mots de liaison » ne sont qu'un lien, et l'objectif ou l'intervention viennent après le diagnostic.\\n\\nSource : Documents de révision L3 Médecine, Partie VI Soins infirmiers (sources de difficultés selon V. Henderson, énoncé du diagnostic infirmier)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__6\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Lequel des éléments suivants est un mode de collecte de données dans la démarche scientifique en soins infirmiers ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'analyse des données\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le plan de soin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'observation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'objectif de soins\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. L'observation\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La collecte des données se fait par l'entrevue, l'examen physique et l'observation. L'analyse des données, le plan de soins et l'objectif de soins sont des étapes ultérieures de la démarche de soins, pas des modes de collecte.\\n\\nSource : Documents de révision L3 Médecine, Partie VI Soins infirmiers (étapes nécessaires à la collecte de données)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__7\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Relevez le diagnostic infirmier qui est en rapport avec la personne de FFF ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Détresse psychologique reliée au licenciement et aux difficultés familiales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Altération de l'état nutritionnel liée à la maladie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hyperthermie reliée à une infection sévère\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Diarrhée liée à une infection digestive\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Détresse psychologique reliée au licenciement et aux difficultés familiales\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La question demande le diagnostic « en rapport avec la personne » de FFF, c'est-à-dire avec sa situation propre et non avec la maladie : son licenciement et les inscriptions scolaires non faites de ses 4 enfants traduisent une détresse psychologique. Les autres propositions (hyperthermie, diarrhée, état nutritionnel) sont en rapport avec la maladie.\\n\\nSource : Documents de révision L3 Médecine, Partie VI Soins infirmiers (diagnostic infirmier « en rapport avec la personne d'un malade »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__8\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Choisissez entre ceux-ci, l'objectif de soins prioritaire de FFF\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Assurer une surveillance rapprochée de l'état de conscience et des paramètres vitaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Assurer une alimentation équilibrée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prévenir les complications neurologiques et circulatoires de l'hyperthermie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ramener la température corporelle de FFF entre 36,5°C et 37,5°C\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Ramener la température corporelle de FFF entre 36,5°C et 37,5°C\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'objectif doit répondre au problème prioritaire, l'hyperthermie à 40 °C, et être mesurable : ramener la température entre 36,5 °C et 37,5 °C. Les autres propositions sont des actions de surveillance ou de prévention, ou ne répondent pas au problème prioritaire.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, plan de soins d'un patient atteint de pneumonie (hyperthermie → retrouver la température normale)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__9\",\n       \"num\": \"10\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE — Vous assurez la permanence de nuit aux urgences médicales de l'EPHR de Korhogo avec le major. Vous recevez FFF 54 ans marié, père de 4 enfants scolarisés, dans une école privée dont les inscriptions n'ont pas été faites à ce jour ; il est amaigri, présente un état d'hébétude avec quelques fois un délire. Son tableau est fait aussi de diarrhée faite de selles fétides d'aspect jus de papaye. La mesure des paramètres vitaux donne une Température de 40°C depuis plus de trois jours, ce qui a obligé l'infirmier de lui poser des vessies de glace. On note un pouls de 86 pulsations par minutes. À l'ouverture de la bouche vous constatez une langue saburrale (sale, pâteuses). Son épouse signale que FFF a été licencié de la SURCAF 2 où il occupait un poste de cadre supérieur. La maladie a débuté par des céphalées, des vertiges, l'insomnie avec un saignement ando-nasal. Le major vous pose les questions suivantes, auxquelles vous répondez :\",\n       \"text\": \"Identifiez le besoin prioritaire de FFF parmi ceux-ci selon le modèle conceptuel de Virginia Henderson\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dormir et se reposer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Éliminer les déchets biologiques\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Maintenir la température dans les limites de la normale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Éviter les dangers\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Maintenir la température dans les limites de la normale\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Avec 40 °C depuis plus de 3 jours, le besoin le plus perturbé est « maintenir la température du corps dans les limites de la normale ». Le cours relie l'hyperthermie d'origine infectieuse à ce besoin.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, plan de soins d'un patient atteint de pneumonie (besoin : maintenir la température du corps dans les limites de la normale)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants, indiquez la complication de la cirrhose du foie liée à l'hypertension portale :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ascite\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hépatite virale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ictère grave\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Abcès du foie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Ascite\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'ascite est le plus souvent la conséquence de l'hypertension portale associée à la rétention hydro-sodée de l'insuffisance hépatique ; le syndrome œdémato-ascitique est l'accident évolutif le plus fréquent de la cirrhose. L'ictère grave relève de l'insuffisance hépatocellulaire ; l'hépatite virale est une cause, non une complication.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Sémiologie hépatique (5.3 Hypertension portale, 5.4 Ascite) et Cirrhose décompensée\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous recevez SSS pour une sensation de faim douloureuse épigastrique évoluant par poussées, rythmée par les repas. SSS souffre de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Reflux gastro-œsophagien\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ulcère gastrique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pancréatite aiguë\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Gastrite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Ulcère gastrique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le syndrome ulcéreux typique est une douleur épigastrique à type de crampe ou de faim douloureuse, calmée par les aliments, rythmée par les repas et évoluant par poussées : c'est l'ulcère gastroduodénal. Le RGO donne surtout un pyrosis, la pancréatite une douleur en barre transfixiante.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Ulcère gastro-duodénal et gastrite, III. Diagnostic positif (syndrome ulcéreux typique)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'un des signes cliniques suivants se rencontre dans l'insuffisance cardiaque gauche, identifiez-le\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Œdème des membres inférieurs\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Asthénie intense\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Turgescence des jugulaires\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Orthopnée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Orthopnée\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Dans l'insuffisance ventriculaire gauche, le sang stagne en amont, dans les poumons : la dyspnée domine (dyspnée d'effort, puis de décubitus = orthopnée), avec toux et expectorations. Les œdèmes des membres inférieurs et la turgescence des jugulaires sont des signes d'insuffisance cardiaque droite.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Affections du myocarde, A. Insuffisance ventriculaire gauche (physiopathologie et signes cliniques) ; Cours de sémiologie médicale et pathologies respiratoires, dyspnée de décubitus\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rage est une maladie infectieuse d'origine :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bactérienne\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Parasitaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mycosique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Virale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Virale\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La rage est une maladie virale grave des mammifères dont l'homme, due à un virus qui provoque une encéphalite ; c'est une zoonose transmise surtout par morsure.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), La rage, I. Définition\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle des affections suivantes est une étiologie du reflux gastro-œsophagien ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La sclérodermie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pancréatite aiguë\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La régurgitation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La gastrite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La sclérodermie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours cite parmi les étiologies particulières du RGO les maladies de système altérant le muscle lisse, dont la sclérodermie (qui diminue la pression du sphincter inférieur de l'œsophage). La régurgitation est un symptôme du RGO, non une cause.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Le reflux gastro-œsophagien, 3.2 Étiologies particulières\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La période d'incubation lors de l'infestation par le virus de l'hépatite B est en moyenne de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"50 à 150 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"15 à 90 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"30 à 100 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"15 à 45 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 50 à 150 jours\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'incubation de l'hépatite B est longue : en moyenne de 50 à 150 jours (environ 2 à 3 mois), plus longue que celle de l'hépatite A (15 à 45 jours). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La contamination par le virus de l'hépatite B (choisissez la bonne réponse) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Peut être faite par l'eau polluée par le virus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fait partie des infections non transmissibles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Peut être faite par la voie digestive\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Doit faire rechercher systématiquement une infection par le virus VIH et la syphilis\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Doit faire rechercher systématiquement une infection par le virus VIH et la syphilis\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'hépatite B fait partie des infections sexuellement transmissibles et doit faire rechercher systématiquement une infection par le VIH et les autres IST (syphilis). La transmission par l'eau ou la voie digestive concerne les hépatites A et E.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Hépatites virales, IV. Virus de l'hépatite B\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les maladies virales pouvant être transmises par voie sexuelle on trouve principalement :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hépatite à virus B\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hépatite à virus A\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hépatite à virus C\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hépatite médicamenteuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Hépatite à virus B\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Parmi les hépatites, c'est le VHB qui se transmet principalement par voie sexuelle (avec la voie périnatale et le sang). Le VHA se transmet par voie féco-orale et le VHC principalement par voie parentérale (sang).\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Hépatites virales (II. VHA, IV. VHB, V. VHC)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la proposition juste parmi les suivantes concernant l'asthme ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'asthme se manifeste par une dyspnée expiratoire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cette dyspnée est à recrudescence diurne\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une toux est souvent associée à la dyspnée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'asthme se manifeste par une dyspnée inspiratoire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. L'asthme se manifeste par une dyspnée expiratoire\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'asthme se traduit par une bradypnée expiratoire sifflante : l'expiration est lente, pénible et longue. La crise survient généralement la nuit (et non le jour) ; la dyspnée n'est pas inspiratoire.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, L'asthme (3.1 Définition, 3.3 Tableau clinique)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La voie de contamination prédominante du sida est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La voie sexuelle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La voie transplacentaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La voie sanguine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'allaitement maternel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La voie sexuelle\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La voie sexuelle est la voie de contamination la plus fréquente du VIH dans le monde ; les voies sanguine et mère-enfant (transplacentaire, allaitement) existent mais sont moins fréquentes. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La mise au point d'un vaccin contre le sida s'avère difficile car\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le VIH est un rétrovirus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le VIH est différent d'un individu à l'autre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le VIH s'attaque au système immunitaire de l'individu\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le VIH effectue des mutations fréquentes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Le VIH effectue des mutations fréquentes\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le VIH est un rétrovirus dont la transcriptase inverse fait beaucoup d'erreurs : le virus mute très souvent et change ses protéines d'enveloppe, ce qui empêche le vaccin de produire une immunité durable contre toutes les variantes. Être un rétrovirus ou attaquer le système immunitaire n'est pas en soi la raison principale. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le sida est une (cochez la bonne réponse) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pandémie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Épidémie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Épizootie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Endémie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Pandémie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le sida touche tous les continents à la fois : c'est une pandémie (le cours de tuberculose parle de « pandémie du VIH »). L'épidémie est limitée dans le temps et l'espace, l'endémie est permanente dans une région, l'épizootie concerne les animaux.\\n\\nSource : Tuberculose, Intérêts (intérêt épidémiologique : pandémie du VIH)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquez le signe clinique habituel de la dysenterie à shigella (dysenterie bacillaire)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ulcérations de la muqueuse colique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fièvre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Diarrhée glaireuse, sanglante\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Éruption cutanée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Diarrhée glaireuse, sanglante\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le signe habituel de la shigellose est une diarrhée glairo-muco-sanglante, afécale, avec épreintes et ténesme. La fièvre est présente dès l'invasion mais n'est pas spécifique ; les ulcérations coliques sont une lésion vue à l'endoscopie, pas un signe clinique.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Les syndromes dysentériques, II. Shigellose (2-2-2 Période d'état)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ensemble de signes qui caractérise le mieux le syndrome dysentérique est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Diarrhée de selles pâteuses intermittentes avec douleurs abdominales diffuses\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Diarrhée graisseuse avec amaigrissement progressif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Diarrhée aqueuse abondante accompagnée de vomissements et de déshydratation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Diarrhée glairo-sanglante avec épreintes et ténesme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Diarrhée glairo-sanglante avec épreintes et ténesme\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le syndrome dysentérique associe une diarrhée glaireuse, parfois sanglante, avec douleurs abdominales, épreintes, ténesme et faux besoins. La diarrhée aqueuse abondante avec vomissements est le syndrome cholériforme ; la diarrhée graisseuse oriente vers une insuffisance pancréatique.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Sémiologie digestive (« Syndrome cholériforme ou dysentérique ? »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'origine d'une hématémèse peut être :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le gastre (l'estomac)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le côlon transverse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La bouche\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le sigmoïde\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Le gastre (l'estomac)\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hématémèse est le rejet de sang par la bouche lors d'un effort de vomissement ; elle traduit une hémorragie digestive haute (ulcère gastroduodénal, varices œsophagiennes…), donc l'estomac (« gastre ») peut en être l'origine. Le côlon et le sigmoïde saignent par l'anus ; la bouche n'est pas une origine d'hématémèse.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Sémiologie digestive, 3.3 Vomissements (Hématémèse)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le méléna est une émission par l'anus de sang digéré\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"spumeux et fétide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"noir et fétide\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"rouge et fétide\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"ocre et fétide\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. noir et fétide\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le méléna est l'émission par l'anus de sang digéré, noir et fétide ; il témoigne d'un saignement situé en amont du côlon droit (« vieux sang »).\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Sémiologie digestive, 3.3 Vomissements (Hématémèse et méléna)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'expectoration est le produit des sécrétions\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pharyngées\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rhinopharyngées\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Œsophagiennes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pulmonaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Pulmonaires\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'expectoration est le rejet par la bouche, lors de la toux, des sécrétions provenant des voies respiratoires inférieures (bronches et poumons). Les sécrétions pharyngées, rhinopharyngées ou œsophagiennes ne constituent pas une expectoration. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La colique désigne :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"l'inflammation d'un organe creux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"les contractures répétées d'un organe creux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"les contractures répétées d'un organe\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"l'inflammation d'un organe plein\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. les contractures répétées d'un organe creux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une colique est une douleur due à des contractions répétées d'un organe creux (tube digestif, voies urinaires, voies biliaires…). Il ne faut pas la confondre avec la colite, qui est une inflammation du côlon.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Sémiologie digestive, 4.3 Douleur colique (« Colique ou colite ? »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'un des signes suivants peut être associé à un syndrome dyspepsique :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La diarrhée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le ballonnement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le vomissement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La constipation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Le ballonnement\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le syndrome dyspepsique associe des symptômes vagues : inconfort, pesanteur, ballonnement, plénitude gastrique, digestion prolongée.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Sémiologie digestive, 3.5 Le syndrome dyspepsique\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'épreinte est une\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"colique qui apparaît après l'évacuation du rectum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"envie impérieuse d'aller à la selle avec douleur abdominale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"douleur intense de l'anus avec selles glaireuses\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"dyspepsie accompagnée de fausses selles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. envie impérieuse d'aller à la selle avec douleur abdominale\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'épreinte est une douleur abdominale à type de colique (contraction douloureuse et répétitive du côlon) qui s'achève par une envie pressante et impérieuse d'aller à la selle. Le ténesme, lui, est une contraction douloureuse de l'anus, avant ou après l'évacuation du rectum.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Sémiologie digestive (Épreinte, Ténesme)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La colique néphrétique est une\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"douleur de distension aiguë de la voie excrétrice\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"douleur atroce vésicale et hépatique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"douleur pénible de l'angle costo-vertébral et lombaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"douleur intense et paroxystique sus-pubienne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. douleur de distension aiguë de la voie excrétrice\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La colique néphrétique est un syndrome douloureux traduisant la mise en tension aiguë de la voie excrétrice au-dessus d'un obstacle (le plus souvent un calcul). La douleur est lombaire, unilatérale, irradiant vers les organes génitaux, et non vésicale ou sus-pubienne.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Lithiase urinaire, IV. Manifestations cliniques\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pollakiurie est une augmentation de la fréquence des mictions avec diurèse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"perturbée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"augmentée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"conservée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"diminuée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. conservée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La pollakiurie est l'augmentation de la fréquence des mictions avec une diurèse (volume total d'urines sur 24 h) conservée : le patient urine souvent, mais peu à chaque fois. Si la diurèse augmente, on parle de polyurie. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'oligurie chez l'adulte, la diurèse est comprise entre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"100 ml et 700 ml par 24 heures\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"100 ml et 300 ml par 24 heures\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"100 ml et 500 ml par 24 heures\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"100 ml et 900 ml par 24 heures\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 100 ml et 500 ml par 24 heures\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Chez l'adulte, l'oligurie correspond à une diurèse inférieure à 500 ml par 24 heures ; en dessous de 100 ml, on parle d'anurie.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Insuffisance rénale aiguë, III. Physiopathologie (oligurie : volume quotidien < 500 ml)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hématurie est la présence de\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémoglobines dans les urines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Leucocytes dans les urines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Bilirubines dans les urines\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hématies dans les urines\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Hématies dans les urines\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'hématurie est la présence de sang, c'est-à-dire d'hématies (globules rouges), dans les urines. L'hémoglobinurie est la présence d'hémoglobine libre, la leucocyturie celle de leucocytes. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La présence d'albumine dans les urines est la\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Acétonurie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Protéinurie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Myoglobinurie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pneumaturie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Protéinurie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'albumine est une protéine : sa présence dans les urines est une protéinurie (dans le syndrome néphrotique, la fuite de protéines porte notamment sur l'albumine). L'acétonurie concerne les corps cétoniques, la myoglobinurie la myoglobine, la pneumaturie l'émission de gaz dans les urines.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Syndrome néphrotique, II. Physiopathologie\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle des affirmations suivantes est exacte ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'origine de la lésion, dans l'hématurie initiale, est urétérale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'origine de la lésion, dans l'hématurie initiale, est urétrale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'origine de la lésion, dans l'hématurie totale, est prostatique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'origine de la lésion, dans l'hématurie terminale, est rénale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. L'origine de la lésion, dans l'hématurie initiale, est urétrale\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans l'épreuve des trois verres, l'hématurie initiale (1er verre) traduit une lésion de l'urètre (ou de la prostate), l'hématurie terminale (3e verre) une lésion vésicale (col de la vessie), l'hématurie totale une origine rénale ou haute. Les autres propositions inversent ces origines. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une douleur thoracique déclarée par le client est un signe\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"subjectif d'une pathologie respiratoire ou cardiaque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"physique d'une pathologie respiratoire ou cardiaque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"paraclinique d'une pathologie respiratoire ou cardiaque\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"objectif d'une pathologie respiratoire ou cardiaque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. subjectif d'une pathologie respiratoire ou cardiaque\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une douleur rapportée par le patient est un signe subjectif (un symptôme fonctionnel) : on ne peut ni la voir ni la mesurer directement. Le cours classe la douleur thoracique parmi les symptômes fonctionnels de la pathologie respiratoire. Les signes physiques et objectifs sont constatés par l'examinateur ; les signes paracliniques viennent des examens.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, Les principaux symptômes, I. Les symptômes fonctionnels (1-2-6 Douleur thoracique)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hémoptysie est du sang rouge qui survient après un effort de toux et qui provient de l'étage moyen\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"du pharynx\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"de la trachée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"du larynx\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"de la glotte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. de la trachée\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'hémoptysie est le rejet par la bouche de sang rouge provenant des voies aériennes sous-glottiques, après un effort de toux. La trachée fait partie de ces voies sous-glottiques.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, 1-2-3 Hémoptysie ; Sémiologie respiratoire, IV. L'hémoptysie\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La dyspnée avec rythme respiratoire sans pause\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"inférieure à 16 cycles est une orthopnée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"inférieure à 10 cycles est une bradypnée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"inférieure à 16 cycles est une apnée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"supérieure à 10 cycles est une tachypnée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. inférieure à 10 cycles est une bradypnée\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La bradypnée est un ralentissement du rythme respiratoire (fréquence très basse, ici moins de 10 cycles/min), alors que la polypnée ou tachypnée est une accélération. L'apnée est l'arrêt complet de la respiration (donc avec pause), et l'orthopnée est une dyspnée en position couchée, sans lien avec la fréquence.\\n\\nSource : Cours de sémiologie médicale et pathologies respiratoires, 1-2-5 La dyspnée et 1-2-7 L'apnée\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les précordialgies cardiaques sont d'origine :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Neurologique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Psychosomatique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ischémique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pleuropulmonaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Ischémique\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les précordialgies d'origine cardiaque sont surtout ischémiques : l'angine de poitrine et l'infarctus du myocarde sont dus à une baisse de l'apport en oxygène au myocarde par atteinte des coronaires (cardiopathies ischémiques).\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Les maladies cardiovasculaires, I. Les maladies des coronaires (angine de poitrine)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Schistosoma mansoni est responsable d'une bilharziose intestinale et parfois hépatosplénique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À la phase d'état, la bilharziose à Schistosoma mansoni est dominée par les manifestations intestinales (selles molles, glaireuses, parfois sanglantes) et hépatospléniques (gros foie, grosse rate).\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Les bilharzioses, 2-3-2 Bilharziose à Schistosoma mansoni\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant un seul cas de choléra, l'IDE n'est pas obligé d'informer son supérieur hiérarchique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"C'est FAUX : le choléra est une maladie à déclaration obligatoire. Même un seul cas doit être signalé sans délai à la hiérarchie (et aux autorités sanitaires) pour déclencher les mesures de lutte contre l'épidémie.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Choléra, 1. Définition (maladie à déclaration obligatoire)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Schistosoma haematobium est l'agent pathogène de la bilharziose uro-génitale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"S. haematobium est l'agent de la bilharziose uro-génitale (hématurie terminale, cystite, complications génitales).\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Bilharzioses, § 2-3-1 et 5-4\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les serpents sont tous zoophages\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours le dit textuellement : les serpents sont tous zoophages (ils se nourrissent d'animaux).\\n\\nSource : Cours de venimologie générale, II.1 Biologie des ophidiens\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La plupart des serpents sont ovipares mais certains sont ovovivipares\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours le dit textuellement : la plupart des serpents sont ovipares, mais certains sont ovovivipares, surtout dans les régions froides.\\n\\nSource : Cours de venimologie générale, II.1 Biologie des ophidiens\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les diabètes types 1 et 2, l'installation de la gangrène au pied est l'une des complications invalidantes et redoutables de ces affections\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"C'est VRAI : le diabète (types 1 et 2) favorise l'artériopathie des membres inférieurs, dont le stade ultime comporte des troubles trophiques et la gangrène ; l'amputation des membres inférieurs fait partie des conséquences majeures du diabète.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Artériopathie oblitérante des membres inférieurs (stade IV, complications) ; Documents de révision L3 Médecine, Partie II, chapitre 1 Le diabète\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'une des complications de l'HTA est l'AVC ischémique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction retient FAUX. Pourtant, le cours range l'AVC dû à une ischémie cérébrale parmi les complications cérébrales de l'HTA (avec l'accident ischémique transitoire).\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, Hypertension artérielle, 6.2 Complications sur le cerveau\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La maturation des éruptions varicelleuses se fait comme suit : macules rosées, puis vésicules, puis croûtes en trois jours\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la varicelle, l'éruption commence par des macules rosées, puis des papules surmontées en 24 h d'une vésicule « en goutte de rosée » qui se dessèche en 48 h ; une croûte apparaît vers le 3e-4e jour. L'éruption évolue donc de la macule à la croûte en quelques jours.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Varicelle-Zona, phase d'état de la varicelle\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle de déshydratation moyenne lorsque la perte hydrique est inférieure à 5% du poids corporel\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction retient VRAI. Le cours, lui, classe la déshydratation selon la perte de poids : légère si < 5 %, moyenne (modérée) entre 5 et 10 %, sévère si > 10 %.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Choléra, 2.3 Phase d'état (stades de la déshydratation)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'euthanasie est un droit du soignant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"C'est FAUX : le soignant n'a pas le droit de provoquer délibérément la mort. Les soins palliatifs ne cherchent ni à accélérer ni à repousser la mort, mais à soulager et à préserver la meilleure qualité de vie jusqu'au décès.\\n\\nSource : Gériatrie PP L2, chapitre II Soins palliatifs (généralités)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'OMS recommande avant tout traitement de paludisme de faire un TDR ou la recherche des plasmodiums par microscopie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"C'est VRAI : avant de traiter, le paludisme doit être confirmé par un test de diagnostic rapide (TDR) ou par la microscopie (goutte épaisse et frottis sanguin), qui est l'examen de référence.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, V. Diagnostic (TDR, microscopie)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le terme néphropathie gravidique « ajoutée » désigne les accidents gravidiques survenant chez les femmes atteintes d'hypertension ou de néphropathie préexistante\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours le définit ainsi : la néphropathie gravidique « ajoutée » désigne les accidents gravidiques survenant chez les femmes atteintes d'hypertension ou de néphropathie préexistante. Elle apparaît dès les premiers mois, peut survenir à n'importe quelle grossesse et récidive.\\n\\nSource : Cours Médecine IDE 2 INFAS actualisé 2020, La néphropathie gravidique (néphropathie gravidique « ajoutée »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__52\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'épreuve des trois verres, s'il y a du sang dans le troisième verre, l'hématurie est d'origine vésicale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction retient FAUX. En sémiologie, le sang dans le 3e verre correspond à une hématurie terminale, classiquement d'origine vésicale (col de la vessie) ; c'est d'ailleurs le type d'hématurie de la bilharziose uro-génitale, qui atteint la vessie.\\n\\nSource : Cours Pathologies tropicales L1 (INFAS Daloa 2017-2018), Bilharziose à S. haematobium (hématurie terminale) ; Cours de venimologie générale, exercices de néphro-urologie (hématurie)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__53\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le RAA est une maladie qui « mord le cœur et lèche les articulations »\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Cet adage décrit bien le RAA : les manifestations articulaires sont bruyantes mais sans gravité ni séquelles (il « lèche les articulations »), tandis que l'atteinte cardiaque est discrète mais grave et seule à laisser des séquelles (il « mord le cœur »).\\n\\nSource : Cours de maladies infectieuses et parasitaires, Rhumatisme articulaire aigu, I. Définition et II. Étude clinique\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j2-ide3__54\",\n       \"num\": \"55\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une morsure de serpent n'entraîne pas toujours d'envenimation et celle-ci n'évolue pas inéluctablement vers la mort, même en l'absence de traitement.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours le dit textuellement : une morsure de serpent n'entraîne pas toujours d'envenimation (morsure « sèche »), et celle-ci n'évolue pas inéluctablement vers la mort, même sans traitement.\\n\\nSource : Cours de venimologie générale, II.4 Signes cliniques et prise en charge des morsures de serpents\",\n       \"sourceDoc\": \"Prépa D.E — J2 Médecine IDE3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_MEDECINE_IDE3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
